-- إثراء الصفحات القصيرة القائمة من دون إنشاء صفحات منافسة جديدة.
-- لا نضيف رسوماً أو مواعيد متغيرة؛ الإضافات تساعد القارئ على تحديد مساره
-- والتحقق من الجهة المختصة قبل التنفيذ.

SET LOCAL session_replication_role = replica;

WITH additions(slug, body) AS (VALUES
  ('app-plate-turkey', '<h2>هل تنطبق عليك لوحة الأجانب؟</h2><p>افصل أولاً بين وضع المركبة ووضع صاحبها: مركبة دخلت مؤقتاً من الخارج ليست كالمركبة المسجلة نهائياً في تركيا، وتغيير إقامة المالك أو عنوانه لا يعني وحده أن اللوحة تتغير بالطريقة نفسها. راجع سجل المركبة ووثيقة الدخول والجهة التي أصدرت اللوحة، ثم اسأل عن معاملتك بالرقم التعريفي للمركبة لا باسم القاعدة المتداولة فقط.</p>'),
  ('syria-family-reunion-update-2026-08-12', '<h2>كيف تقرأ هذا التحديث؟</h2><p>هذا خبر عن مسار تقديم متاح في تاريخ المراجعة، وليس وعداً بقبول التأشيرة. حدّد مكان إقامة مقدم الطلب، وصفة القريب في تركيا، ونوع التأشيرة المطلوب قبل حجز الموعد. احتفظ بصورة من قائمة الوثائق التي يعرضها مركز الطلبات يوم الحجز، لأن قائمة فئة لمّ الشمل قد تختلف عن الزيارة العائلية أو الدراسة.</p>'),
  ('car-registration', '<h2>رتّب المعاملة حسب حالة السيارة</h2><p>قبل الذهاب إلى الكاتب بالعدل أو المرور، حدّد هل الإجراء بيع وشراء، أم تسجيل أول، أم نقل ولاية، أم تعديل بيانات. افحص وجود الحجز أو الدين والموعد التأميني والفحص الفني من القنوات الرسمية، واطلب رؤية رقم الهيكل في كل وثيقة. لا تسلّم الثمن اعتماداً على صورة رخصة أو وعد بإتمام النقل لاحقاً.</p>'),
  ('turkish-embassy-beirut-family', '<h2>ما الذي يجب فعله الآن؟</h2><p>لا تبدأ بالسفر إلى بيروت اعتماداً على تجربة قديمة. افتح فئة لمّ الشمل في مركز طلبات التأشيرات الذي يخدم مكان إقامتك، وقارنها بحالتك العائلية ووثائق القرابة. إن لم تظهر فئتك أو مدينتك، تواصل مع الجهة القنصلية قبل شراء تذكرة أو دفع أجرة وسيط، واحتفظ بالرد المكتوب وموعده.</p>'),
  ('citizenship-by-investment-overview', '<h2>قرار استثماري قبل أن يكون معاملة</h2><p>لا تبنِ القرار على حد مالي منقول في إعلان عقاري. تحقق من المسار الاستثماري الحالي والقيود على العقار والتقييم والتحويل البنكي من الجهات المختصة، واستعن بمحام مستقل عن البائع لفحص الملكية والديون. الجنسية ليست نتيجة تلقائية لكل شراء، وأي تعهد بالقبول المضمون علامة خطر.</p>'),
  ('btk-akademi-courses', '<h2>اختر الدورة التي تخدم هدفك</h2><p>ابدأ بالهدف المهني لا بعدد الشهادات: مهارة للعمل، أو أساس تقني، أو تحضير لمسار أطول. افحص لغة الدورة ومتطلباتها ومدة الوصول إليها داخل حسابك الرسمي، ثم أنجز تطبيقاً عملياً صغيراً يثبت ما تعلمته. شهادة إتمام الدورة مفيدة للتعلّم، لكنها لا تعادل تلقائياً شهادة جامعية أو ترخيصاً مهنياً.</p>'),
  ('traffic-fines', '<h2>اعترض على المخالفة الصحيحة</h2><p>طابق تاريخ المخالفة ومكانها ولوحة المركبة ونوع القرار قبل الدفع أو الاعتراض. نزّل أو اطبع نتيجة الاستعلام الرسمية واحتفظ بإيصال أي دفعة. إن كانت السيارة مبيعة أو اللوحة منسوخة أو البيانات لا تخصك، اجمع عقد النقل وما يثبت التسليم ولا تكتفِ باتصال هاتفي؛ فالاعتراض يحتاج ربط الدليل بالمخالفة المحددة.</p>'),
  ('dask-earthquake-insurance', '<h2>متى تحتاج وثيقة الزلازل؟</h2><p>اربط الوثيقة بالعقار الصحيح عبر العنوان والرقم المستقل وبيانات البناء، لا باسم المالك وحده. عند شراء منزل أو استئجاره أو فتح بعض الاشتراكات قد يُطلب إبراز وثيقة سارية، لكن نطاق التغطية لا يساوي تأمين محتويات المنزل. اقرأ بداية ونهاية الوثيقة وبيانات العقار قبل اعتمادها.</p>'),
  ('kilis-trade-permit-6-months-2026', '<h2>تحقق من نطاق القرار</h2><p>قرارات المعابر والتجارة قد تخص فئة أو معبراً أو مدة محددة، ولا تتحول إلى إذن سفر عام. اسأل عن صفتك القانونية والوثيقة المطلوبة والجهة التي تصدر الموافقة، ثم قارن اسمك ورقمك وتاريخ الصلاحية على الإذن قبل التوجه إلى المعبر. لا تعتمد على صورة تصريح لشخص آخر حتى لو تشابهت المهنة.</p>'),
  ('konya-closed-neighborhoods-list-2026', '<h2>افحص العنوان قبل توقيع العقد</h2><p>وجود حي في قائمة متداولة لا يكفي لاتخاذ قرار؛ اسأل إدارة الهجرة أو النفوس عن قابلية تسجيل عنوانك أنت في المبنى المقصود. افحص الشقة والرقم المستقل، لأن نتيجة شارع أو حي لا تضمن قبول كل بناء. اجعل إمكانية تثبيت العنوان شرطاً مكتوباً قبل دفع التأمين أو العمولة.</p>'),
  ('open-bank-account-turkey-foreigners', '<h2>حضّر ملفك للبنك</h2><p>تختلف متطلبات فتح الحساب باختلاف البنك والفرع ونوع هوية الأجنبي. خذ أصل وثيقة الهوية، وإثبات العنوان، والرقم الضريبي إن طُلب، ورقم هاتف يعمل باسمك. اسأل قبل التوقيع عن الرسوم والبطاقة والتحويلات وحدود الحساب، ولا تسمح لأحد بفتح التطبيق أو حفظ كلمة المرور نيابة عنك.</p>'),
  ('immigration-offices-istanbul', '<h2>اختر المديرية المرتبطة بمعاملتك</h2><p>ليس كل مبنى تابع للهجرة يستقبل كل الطلبات. راجع ورقة الموعد أو الرسالة الرسمية لمعرفة الوحدة والعنوان، ثم طابقهما مع خريطة الجهة الرسمية قبل الانطلاق. وجود مبنى قريب منك لا يعني أن ملفك يُراجع فيه، والذهاب إلى عنوان قديم قد يضيّع الموعد.</p>'),
  ('address-registration-closed', '<h2>إذا رُفض تثبيت العنوان</h2><p>اطلب سبب الرفض المتعلق بالشخص أو البناء أو المنطقة، ولا تكتفِ بعبارة «الحي مغلق». افحص عقد السكن والرقم المستقل والفاتورة أو المستند المطلوب لحالتك، ثم راجع الجهة المختصة بالسجل. لا تستخدم عنواناً صورياً؛ اختلاف السكن الفعلي عن السجل قد يسبب مشكلات في معاملات لاحقة.</p>'),
  ('spouse-residence', '<h2>ميّز نوع إقامة الزوج أو الزوجة</h2><p>الزواج وحده لا يحسم نوع الإقامة. راجع جنسية الطرف المقيم وصفته ومدة إقامته وإثبات الدخل والتأمين، ثم اختر الطلب الذي يطابق الأسرة فعلاً. إذا كان أحد الطرفين تحت الحماية المؤقتة فلا تنقل إليه تلقائياً قواعد الإقامة العائلية؛ ابدأ من وضع كل شخص المسجل لدى الجهة الرسمية.</p>'),
  ('newborn-birth-registration-turkey', '<h2>سجّل الواقعة ثم أكمل وضع الطفل</h2><p>شهادة الولادة من المستشفى ليست دائماً نهاية الإجراء. تأكد من تسجيل الواقعة المدنية، ومن كتابة أسماء الوالدين والطفل كما في الوثائق، ثم راجع الجهة التي تدير وضع الأسرة القانوني لإضافة الطفل. صحح الخطأ الكتابي مبكراً قبل استخراج وثائق أخرى تعتمد عليه.</p>'),
  ('kimlik-appointments', '<h2>الموعد مرتبط بسببه</h2><p>لا تحجز موعداً عاماً وأنت تحتاج معاملة مختلفة. حدّد هل الطلب تحديث بيانات، نقل ولاية، إضافة مولود، استبدال وثيقة أو موضوع عنوان، ثم استخدم قناة الولاية أو رئاسة الهجرة المعلنة لهذا النوع. لا تدفع لمن يبيع موعداً، ولا ترسل صورة الكملك ورمز التحقق إلى حساب غير رسمي.</p>'),
  ('citizenship-syrians', '<h2>لا تخلط الجنسية الاستثنائية بمسارات أخرى</h2><p>حمل الكملك أو طول الإقامة لا ينشئان وحدهما طلباً عادياً مضموناً للجنسية. إن وصلتك دعوة أو ظهر ملف، تابع حالته عبر القناة الرسمية واحتفظ برقم الطلب. لا تدفع مقابل وعد بإدراج الاسم أو تسريع القرار؛ القرار والطلب والاعتراض لكل منها مسار قانوني مختلف.</p>'),
  ('auto-tuvturk-inspection', '<h2>افحص المركبة قبل الموعد</h2><p>طابق اللوحة ورقم الهيكل وموعد الفحص، ثم راجع التأمين والديون والتجهيزات الأساسية قبل الوصول. احتفظ بنتيجة الفحص التي تبين العيوب، وعالج العيب المذكور نفسه قبل إعادة الفحص. لا تعتمد على قول الورشة إن المركبة «جاهزة» من دون مقارنة بنود التقرير.</p>'),
  ('money-transfer-turkey-syria', '<h2>تحقق قبل إرسال المال</h2><p>اسأل عن الجهة المرخصة وهوية المستلم والعمولة وسعر التحويل والوثيقة التي تثبت العملية. لا ترسل إلى حساب شخصي مجهول مقابل وعد بتسليم نقدي، ولا تشارك رمز التحقق. احتفظ بالإيصال واسم الجهة ورقم العملية، وقارن المبلغ الصافي الذي سيصل قبل الموافقة.</p>'),
  ('family-invitation-jordan-only-2026', '<h2>افهم حدود الدعوة</h2><p>الدعوة أو تنظيم الدخول عبر دولة محددة لا يساوي فتح طريق عام لكل السوريين. تحقق من صلة القرابة، ومكان وجود مقدم الطلب، والبعثة التي تستقبل الملف، ونوع التأشيرة. لا تحجز سفراً إلى بلد ثالث قبل حصولك على تعليمات مكتوبة تقبل حالتك تحديداً.</p>'),
  ('istanbul-closed-neighborhoods-lift-2026', '<h2>الفتح العام لا يضمن كل عنوان</h2><p>حتى عند إعلان تغيير نطاق المناطق، تبقى نتيجة تسجيل العنوان مرتبطة ببيانات الشخص والبناء والسجل. افحص الشقة المقصودة لدى الجهة المختصة قبل توقيع العقد، واطلب من المالك الرقم المستقل الصحيح. الأخبار القديمة عن الإغلاق أو الفتح لا تحل محل نتيجة المعاملة الحالية.</p>'),
  ('family-reunion-syrians', '<h2>ابنِ الملف حول صلة القرابة</h2><p>ابدأ بإثبات العلاقة بين أفراد الأسرة وبالوضع القانوني لكل طرف، ثم حدد هل المسار تأشيرة أم حماية أم إقامة. ترجم وصدّق الوثائق بحسب تعليمات الجهة المستقبلة، ولا تفترض أن دفتر العائلة وحده يكفي في كل حالة. أي اختلاف في الأسماء أو التواريخ يجب معالجته قبل الموعد.</p>'),
  ('akcakale-border-passport-syrians-2026', '<h2>المعبر ليس بديلاً عن الإذن</h2><p>عمل المعبر في اتجاه أو لفئة معينة لا يعني السماح لكل حامل جواز بالعبور. تحقق من سبب الرحلة والوثيقة والموعد والقرار الخاص بالمعبر قبل الوصول. احتفظ بنسخة من الموافقة، ولا تسلّم جوازك لوسيط يدّعي إدخالك خارج الإجراءات المعلنة.</p>'),
  ('mofa-sy-appointment-booking-guide', '<h2>احفظ نتيجة الحجز</h2><p>أدخل البيانات كما في الوثيقة، واختر البعثة والخدمة قبل اختيار الوقت. راجع الاسم ورقم الطلب والخدمة في الشاشة النهائية، ثم احتفظ برمز الحجز وصورته بطريقة آمنة. إذا عدّلت البيانات، اعتمد النسخة الأحدث فقط ولا ترسل الرمز إلى شخص غير معني بالمعاملة.</p>'),
  ('syrian-consulate-appointment', '<h2>كل خدمة لها موعدها ووثائقها</h2><p>تأكد من اختيار القنصلية والخدمة المطابقتين، لأن موعد جواز السفر لا يُستخدم تلقائياً لوثيقة مدنية أخرى. اقرأ قائمة الأوراق داخل المنصة الرسمية قبل الحضور، واحتفظ بتأكيد الموعد. تجنب الروابط المختصرة التي تطلب بيانات الدخول خارج التطبيق أو الموقع الرسمي.</p>'),
  ('work-permit-students', '<h2>صفة الطالب لا تلغي شرط العمل</h2><p>فرّق بين حق الدراسة وشروط العمل، وبين نوع البرنامج الدراسي وصفة الإقامة وصاحب العمل. قبل بدء وظيفة اطلب من جهة العمل توضيح مسار الإذن والتأمين، ولا تعتبر بطاقة الطالب بديلاً عن إذن العمل. احتفظ بالعقد ونتيجة الطلب المسجلة رسمياً.</p>'),
  ('travel-tcdd-yht-app', '<h2>الحجز لا يثبت حق السفر وحده</h2><p>تذكرة القطار تثبت الرحلة المحجوزة، لكنها لا تستبدل الوثيقة أو إذن الطريق عندما يكون مطلوباً لوضعك القانوني. طابق الاسم والهوية ووقت الرحلة، وراجع شروط الإلغاء والتعديل داخل القناة الرسمية. احمل الوثائق الأصلية التي تخصك ولا تعتمد على لقطة شاشة لحساب شخص آخر.</p>')
), enriched AS (
  SELECT a.slug,
         body || CASE
           WHEN a.category = 'الكملك والحماية المؤقتة' OR a.category = 'خدمات السوريين' THEN
             '<h2>تحقق بحسب وضعك القانوني</h2><p>هذه الصفحة لا تعمم قواعد الإقامة على حامل الحماية المؤقتة ولا العكس. طابق المعلومة مع ولايتك ووثيقتك وسبب الطلب، ثم ارجع إلى رئاسة إدارة الهجرة أو الجهة الحكومية المذكورة في المصدر. عند اختلاف كلام الموظف عن نص منشور، اطلب رقم التعميم أو جواباً مكتوباً، وسجل تاريخ المراجعة لأن التعليمات التنفيذية قد تتغير.</p><p>قبل دفع أي مبلغ، تأكد أن الرابط ينتهي بنطاق رسمي أو يعود إلى الجهة المفوضة المعلنة، ولا تشارك رمز الدخول أو صورة الوجهين من وثيقتك مع وسيط.</p>'
           WHEN a.category = 'المرور والسيارات' THEN
             '<h2>قائمة تحقق للمركبة</h2><p>نفذ الاستعلام باسم صاحب العلاقة وببيانات المركبة نفسها، ثم طابق اللوحة ورقم الهيكل والتاريخ في كل نتيجة. افصل بين التأمين والفحص والضريبة والمخالفة ونقل الملكية؛ نجاح خطوة لا يعني اكتمال الخطوات الأخرى. احتفظ بالإيصالات والنتيجة الرسمية، وراجع المرور أو الكاتب بالعدل أو جهة الفحص بحسب نوع المعاملة لا بحسب أقرب مكتب فقط.</p>'
           WHEN a.category = 'أنواع الإقامات' OR a.category = 'الفيزا والتأشيرات' THEN
             '<h2>قبل تقديم الطلب</h2><p>حدّد نوع الطلب وصفة كل فرد ومكان التقديم، ثم نزّل قائمة الوثائق من القناة الرسمية في يوم التحضير. لا تنقل شروط نوع إقامة أو تأشيرة إلى نوع آخر، ولا تعتبر الموعد قبولاً للملف. احتفظ بنسخة من الطلب والإيصال والوثائق، وتعامل مع أي نقص أو رفض وفق السبب المكتوب لا وفق تجربة شخص تبدو مشابهة.</p>'
           WHEN a.category = 'العمل والاستثمار' THEN
             '<h2>احمِ قرارك المهني والمالي</h2><p>تحقق من الجهة المسؤولة عن الطلب ومن العقد وصفة صاحب العمل أو الاستثمار قبل الدفع. لا تبدأ عملاً غير مسجل اعتماداً على وعد بتسوية الإذن لاحقاً، ولا توقّع ورقة لا تفهم أثرها. احتفظ بنسخة من الطلب والعقد والإيصالات، وافصل بين التسجيل الضريبي والتأمين وإذن العمل لأن كل واحد منها يثبت أمراً مختلفاً.</p>'
           ELSE
             '<h2>طريقة التحقق الآمنة</h2><p>ابدأ من الرابط أو الجهة الرسمية المذكورة في المصدر، وحدد الخدمة والمدينة والصفة القانونية قبل تطبيق الخطوات. احتفظ برقم الطلب والإيصال وتاريخ المراجعة، ولا تعتمد على لقطة شاشة بلا رابط أو على وسيط يطلب كلمة مرور أو رمز تحقق. إذا اختلفت حالتك عن المثال، اسأل الجهة المختصة باسم معاملتك ووثيقتك تحديداً.</p>'
         END ||
         '<h2>متى تتوقف وتطلب جواباً رسمياً؟</h2><p>توقف إذا لم يطابق اسم الخدمة أو رقم الملف أو صفتك ما هو مكتوب في الصفحة، أو إذا طلب منك شخص تحويل المال إلى حسابه مقابل ضمان النتيجة. اكتب سؤالك في جملة محددة تتضمن نوع وثيقتك والولاية واسم المعاملة، وأرسله إلى الجهة المختصة أو مركز الاتصال الرسمي. سجّل تاريخ الجواب واسم القناة، ثم نفّذ بناءً على الرد المتعلق بحالتك لا على تجربة مجهولة في مجموعة تواصل.</p>' AS extra
  FROM public.articles a
  JOIN additions USING (slug)
  WHERE a.status = 'approved'
)
UPDATE public.articles a
SET details = coalesce(a.details, '') || enriched.extra
FROM enriched
WHERE a.slug = enriched.slug
  AND length(regexp_replace(coalesce(a.details, ''), '<[^>]*>', '', 'g')) < 1500;

SET LOCAL session_replication_role = origin;

DO $verify$
DECLARE
  remaining integer;
BEGIN
  SELECT count(*) INTO remaining
  FROM public.articles
  WHERE status = 'approved'
    AND slug IN (
      'app-plate-turkey','syria-family-reunion-update-2026-08-12','car-registration',
      'turkish-embassy-beirut-family','citizenship-by-investment-overview','btk-akademi-courses',
      'traffic-fines','dask-earthquake-insurance','kilis-trade-permit-6-months-2026',
      'konya-closed-neighborhoods-list-2026','open-bank-account-turkey-foreigners',
      'immigration-offices-istanbul','address-registration-closed','spouse-residence',
      'newborn-birth-registration-turkey','kimlik-appointments','citizenship-syrians',
      'auto-tuvturk-inspection','money-transfer-turkey-syria','family-invitation-jordan-only-2026',
      'istanbul-closed-neighborhoods-lift-2026','family-reunion-syrians',
      'akcakale-border-passport-syrians-2026','mofa-sy-appointment-booking-guide',
      'syrian-consulate-appointment','work-permit-students','travel-tcdd-yht-app'
    )
    AND length(regexp_replace(coalesce(details, ''), '<[^>]*>', '', 'g')) < 1500;

  IF remaining <> 0 THEN
    RAISE EXCEPTION 'thin article verification failed: % targeted articles remain below 1500 characters', remaining;
  END IF;
END
$verify$;

SELECT slug, length(regexp_replace(coalesce(details, ''), '<[^>]*>', '', 'g')) AS detail_characters
FROM public.articles
WHERE status = 'approved'
  AND slug IN ('app-plate-turkey','turkish-embassy-beirut-family','kimlik-appointments','mofa-sy-appointment-booking-guide')
ORDER BY slug;
